#ifndef MLA_PAGED_DECODE_H16_CKV512_KPE64_PS1_KERNEL_H_
#define MLA_PAGED_DECODE_H16_CKV512_KPE64_PS1_KERNEL_H_

#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <torch/extension.h>
#include <cstdint>

// Simple macros for input checks
#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_DTYPE
#define CHECK_DTYPE(x, dtype) TORCH_CHECK(x.scalar_type() == dtype, #x " has wrong dtype")
#endif

// Fixed constants for this kernel
static constexpr int MLA_NUM_QO_HEADS = 16;
static constexpr int MLA_HEAD_DIM_CKV = 512;
static constexpr int MLA_HEAD_DIM_KPE = 64;
static constexpr int MLA_PAGE_SIZE    = 1;

// CUDA launcher declaration
void mla_paged_decode_h16_ckv512_kpe64_ps1_launcher(
    const __nv_bfloat16* q_nope,        // [B, 16, 512]
    const __nv_bfloat16* q_pe,          // [B, 16, 64]
    const __nv_bfloat16* ckv_cache,     // [num_pages, 1, 512] -> treat as [num_pages, 512]
    const __nv_bfloat16* kpe_cache,     // [num_pages, 1, 64]  -> treat as [num_pages, 64]
    const int32_t* kv_indptr,           // [B+1]
    const int32_t* kv_indices,          // [kv_indptr[-1]]
    int batch_size,
    int len_indptr,
    float sm_scale,
    __nv_bfloat16* output,              // [B, 16, 512]
    float* lse,                         // [B, 16]
    cudaStream_t stream);

// Host API exposed to Python
pybind11::dict run(
    torch::Tensor q_nope,       // bf16 [B, 16, 512]
    torch::Tensor q_pe,         // bf16 [B, 16, 64]
    torch::Tensor ckv_cache,    // bf16 [P, 1, 512]
    torch::Tensor kpe_cache,    // bf16 [P, 1, 64]
    torch::Tensor kv_indptr,    // int32 [B+1]
    torch::Tensor kv_indices,   // int32 [kv_indptr[-1]]
    double sm_scale             // float
);

#endif // MLA_PAGED_DECODE_H16_CKV512_KPE64_PS1_KERNEL_H_

#include "kernel.h"
#include <cuda_bf16.h>
#include <math_constants.h>

#define WARP_SIZE 32

// Block-wide reduction using warp shuffles and shared memory.
// 'shared' must have at least (BLOCK_SIZE / WARP_SIZE) floats.
template<int BLOCK_SIZE>
__device__ __forceinline__ float blockReduceSum(float val, float* shared) {
    // Intra-warp reduction
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }

    const int lane = threadIdx.x & (WARP_SIZE - 1);
    const int warp_id = threadIdx.x >> 5; // / WARP_SIZE

    if (lane == 0) {
        shared[warp_id] = val;
    }
    __syncthreads();

    float res = 0.f;
    if (warp_id == 0) {
        const int num_warps = BLOCK_SIZE / WARP_SIZE;
        res = (threadIdx.x < num_warps) ? shared[lane] : 0.f;

        #pragma unroll
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            res += __shfl_down_sync(0xffffffff, res, offset);
        }
        if (lane == 0) {
            shared[0] = res;
        }
    }
    __syncthreads();
    return shared[0];
}

// Kernel implementing streamed softmax attention with online normalization.
// Computes for each (batch b, head h):
//   logits_t = (q_nope[b,h]·Kc[t] + q_pe[b,h]·Kp[t]) * sm_scale
//   out = softmax(logits) @ Kc
//   lse = log2(sum(exp(logits)))
template<int BLOCK_SIZE>
__global__ void mla_paged_decode_h16_ckv512_kpe64_ps1_kernel(
    const __nv_bfloat16* __restrict__ q_nope,      // [B, 16, 512]
    const __nv_bfloat16* __restrict__ q_pe,        // [B, 16, 64]
    const __nv_bfloat16* __restrict__ ckv_cache,   // [P, 1, 512] -> [P, 512]
    const __nv_bfloat16* __restrict__ kpe_cache,   // [P, 1, 64]  -> [P, 64]
    const int32_t* __restrict__ kv_indptr,         // [B+1]
    const int32_t* __restrict__ kv_indices,        // [kv_indptr[-1]]
    int batch_size,
    int len_indptr,
    float sm_scale,
    __nv_bfloat16* __restrict__ output,            // [B, 16, 512]
    float* __restrict__ lse                        // [B, 16]
) {
    constexpr int HD_C = MLA_HEAD_DIM_CKV;
    constexpr int HD_P = MLA_HEAD_DIM_KPE;
    constexpr int NUM_HEADS = MLA_NUM_QO_HEADS;

    const int b = blockIdx.x;
    const int h = blockIdx.y;
    if (b >= batch_size || h >= NUM_HEADS) return;

    const int tid = threadIdx.x;
    const int num_warps = BLOCK_SIZE / WARP_SIZE;
    (void)num_warps;

    extern __shared__ float smem[];
    float* sQn   = smem;                    // [512]
    float* sQp   = sQn + HD_C;              // [64]
    float* sKc   = sQp + HD_P;              // [512]
    float* sKp   = sKc + HD_C;              // [64]
    float* sAcc  = sKp + HD_P;              // [512]
    float* warp  = sAcc + HD_C;             // [num_warps]
    float* scal  = warp + (BLOCK_SIZE / WARP_SIZE); // [4] -> m, s, alpha, w

    // Compute offsets
    const size_t qn_off = (static_cast<size_t>(b) * NUM_HEADS + h) * HD_C;
    const size_t qp_off = (static_cast<size_t>(b) * NUM_HEADS + h) * HD_P;
    const size_t out_off = qn_off;
    const size_t lse_off = static_cast<size_t>(b) * NUM_HEADS + h;

    // Get page range for this sequence
    if (b + 1 >= len_indptr) return;
    const int32_t page_beg = kv_indptr[b];
    const int32_t page_end = kv_indptr[b + 1];
    const int32_t L_tokens = max(0, page_end - page_beg);

    // Pointers
    const __nv_bfloat16* qn_ptr = q_nope + qn_off;
    const __nv_bfloat16* qp_ptr = q_pe   + qp_off;
    __nv_bfloat16* out_ptr = output + out_off;

    // Early exit if no KV for this batch element
    if (L_tokens <= 0) {
        for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
            out_ptr[d] = __float2bfloat16(0.0f);
        }
        if (tid == 0) {
            lse[lse_off] = -CUDART_INF_F;
        }
        return;
    }

    // Load Q vectors (bf16 -> f32) into shared memory
    for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
        sQn[d] = __bfloat162float(qn_ptr[d]);
    }
    for (int d = tid; d < HD_P; d += BLOCK_SIZE) {
        sQp[d] = __bfloat162float(qp_ptr[d]);
    }

    // Initialize sAcc and streaming softmax scalars
    for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
        sAcc[d] = 0.0f;
    }
    if (tid == 0) {
        scal[0] = -CUDART_INF_F; // m
        scal[1] = 0.0f;          // s (sum of exp shifted by m)
        scal[2] = 0.0f;          // alpha (tmp)
        scal[3] = 0.0f;          // w (tmp)
    }
    __syncthreads();

    // Iterate over tokens/pages
    for (int t = 0; t < L_tokens; ++t) {
        const int32_t page_idx = kv_indices[page_beg + t];

        // Load Kc[page_idx] and Kp[page_idx] (bf16 -> f32)
        const __nv_bfloat16* kc_ptr = ckv_cache + static_cast<size_t>(page_idx) * HD_C; // [512]
        const __nv_bfloat16* kp_ptr = kpe_cache + static_cast<size_t>(page_idx) * HD_P; // [64]

        for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
            sKc[d] = __bfloat162float(kc_ptr[d]);
        }
        for (int d = tid; d < HD_P; d += BLOCK_SIZE) {
            sKp[d] = __bfloat162float(kp_ptr[d]);
        }
        __syncthreads();

        // Compute dot products: qn·kc and qp·kp
        float partial_n = 0.0f;
        for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
            partial_n += sQn[d] * sKc[d];
        }
        float dot_n = blockReduceSum<BLOCK_SIZE>(partial_n, warp);

        float partial_p = 0.0f;
        for (int d = tid; d < HD_P; d += BLOCK_SIZE) {
            partial_p += sQp[d] * sKp[d];
        }
        float dot_p = blockReduceSum<BLOCK_SIZE>(partial_p, warp);

        float score = (dot_n + dot_p) * sm_scale;

        // Update streaming softmax variables and accumulation
        if (tid == 0) {
            float m_old = scal[0];
            float s_old = scal[1];
            float m_new = fmaxf(m_old, score);
            float alpha = (m_old == -CUDART_INF_F) ? 0.0f : __expf(m_old - m_new);
            float w = __expf(score - m_new);
            float s_new = s_old * alpha + w;

            scal[0] = m_new;  // m
            scal[1] = s_new;  // s
            scal[2] = alpha;  // alpha
            scal[3] = w;      // w
        }
        __syncthreads();

        const float alpha = scal[2];
        const float w = scal[3];

        // Accumulate numerator: sAcc = sAcc * alpha + w * Kc
        for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
            sAcc[d] = fmaf(w, sKc[d], sAcc[d] * alpha);
        }
        __syncthreads();
    }

    // Normalize by softmax denominator s and write output
    const float s_sum = scal[1];
    const float inv_s = (s_sum > 0.0f) ? (1.0f / s_sum) : 0.0f;
    for (int d = tid; d < HD_C; d += BLOCK_SIZE) {
        out_ptr[d] = __float2bfloat16(sAcc[d] * inv_s);
    }
    if (tid == 0) {
        const float m = scal[0];
        float lse_val = (s_sum > 0.0f) ? (m + logf(s_sum)) * (1.0f / logf(2.0f)) : -CUDART_INF_F;
        lse[lse_off] = lse_val;
    }
}

// Launcher
void mla_paged_decode_h16_ckv512_kpe64_ps1_launcher(
    const __nv_bfloat16* q_nope,
    const __nv_bfloat16* q_pe,
    const __nv_bfloat16* ckv_cache,
    const __nv_bfloat16* kpe_cache,
    const int32_t* kv_indptr,
    const int32_t* kv_indices,
    int batch_size,
    int len_indptr,
    float sm_scale,
    __nv_bfloat16* output,
    float* lse,
    cudaStream_t stream
) {
    if (batch_size <= 0) return;

    constexpr int BLOCK_SIZE = 256;
    const dim3 grid(batch_size, MLA_NUM_QO_HEADS, 1);
    const dim3 block(BLOCK_SIZE, 1, 1);
    const int num_warps = BLOCK_SIZE / WARP_SIZE;
    // Shared memory size in floats:
    // sQn[512] + sQp[64] + sKc[512] + sKp[64] + sAcc[512] + warp[num_warps] + scal[4]
    const size_t shmem_floats = (3 * MLA_HEAD_DIM_CKV) + (2 * MLA_HEAD_DIM_KPE) + num_warps + 4;
    const size_t shmem_bytes = shmem_floats * sizeof(float);

    mla_paged_decode_h16_ckv512_kpe64_ps1_kernel<BLOCK_SIZE>
        <<<grid, block, shmem_bytes, stream>>>(
            q_nope, q_pe, ckv_cache, kpe_cache,
            kv_indptr, kv_indices,
            batch_size, len_indptr, sm_scale,
            output, lse
        );

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "Kernel launch failed: ", cudaGetErrorString(err));
}

#include "kernel.h"

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_bf16.h>
#include <vector>
#include <iostream>

using torch::Tensor;

static inline void check_inputs(
    const Tensor& q_nope,
    const Tensor& q_pe,
    const Tensor& ckv_cache,
    const Tensor& kpe_cache,
    const Tensor& kv_indptr,
    const Tensor& kv_indices
) {
    // Dtype checks
    CHECK_DTYPE(q_nope, torch::kBFloat16);
    CHECK_DTYPE(q_pe,   torch::kBFloat16);
    CHECK_DTYPE(ckv_cache, torch::kBFloat16);
    CHECK_DTYPE(kpe_cache, torch::kBFloat16);
    CHECK_DTYPE(kv_indptr, torch::kInt);
    CHECK_DTYPE(kv_indices, torch::kInt);

    // Dim checks
    TORCH_CHECK(q_nope.dim() == 3, "q_nope must be [B, 16, 512]");
    TORCH_CHECK(q_pe.dim()   == 3, "q_pe must be [B, 16, 64]");
    TORCH_CHECK(ckv_cache.dim() == 3, "ckv_cache must be [P, 1, 512]");
    TORCH_CHECK(kpe_cache.dim() == 3, "kpe_cache must be [P, 1, 64]");
    TORCH_CHECK(kv_indptr.dim() == 1, "kv_indptr must be 1D");
    TORCH_CHECK(kv_indices.dim() == 1, "kv_indices must be 1D");

    // Shape checks (fixed constants)
    TORCH_CHECK(q_nope.size(1) == MLA_NUM_QO_HEADS && q_nope.size(2) == MLA_HEAD_DIM_CKV,
                "q_nope must be [B, 16, 512]");
    TORCH_CHECK(q_pe.size(1) == MLA_NUM_QO_HEADS && q_pe.size(2) == MLA_HEAD_DIM_KPE,
                "q_pe must be [B, 16, 64]");
    TORCH_CHECK(ckv_cache.size(1) == MLA_PAGE_SIZE && ckv_cache.size(2) == MLA_HEAD_DIM_CKV,
                "ckv_cache must be [P, 1, 512] with page_size=1");
    TORCH_CHECK(kpe_cache.size(1) == MLA_PAGE_SIZE && kpe_cache.size(2) == MLA_HEAD_DIM_KPE,
                "kpe_cache must be [P, 1, 64] with page_size=1");

    // Constraint checks
    const int64_t B = q_nope.size(0);
    TORCH_CHECK(kv_indptr.size(0) == B + 1, "len_indptr must be batch_size + 1");

    // kv_indices length equals kv_indptr[-1]
    // Make sure to get a CPU scalar to avoid device sync issues
    Tensor last_cpu = kv_indptr.index({kv_indptr.size(0) - 1}).cpu();
    int64_t kv_count = last_cpu.item<int32_t>();
    TORCH_CHECK(kv_indices.size(0) == kv_count,
                "num_kv_indices must equal kv_indptr[-1]");
}

pybind11::dict run(
    Tensor q_nope,       // bf16 [B, 16, 512]
    Tensor q_pe,         // bf16 [B, 16, 64]
    Tensor ckv_cache,    // bf16 [P, 1, 512]
    Tensor kpe_cache,    // bf16 [P, 1, 64]
    Tensor kv_indptr,    // int32 [B+1]
    Tensor kv_indices,   // int32 [kv_indptr[-1]]
    double sm_scale_d
) {
    check_inputs(q_nope, q_pe, ckv_cache, kpe_cache, kv_indptr, kv_indices);

    const bool inputs_on_cpu =
        !q_nope.is_cuda() || !q_pe.is_cuda() || !ckv_cache.is_cuda() ||
        !kpe_cache.is_cuda() || !kv_indptr.is_cuda() || !kv_indices.is_cuda();

    // Decide device
    c10::Device device = inputs_on_cpu ? c10::Device(c10::kCUDA, 0) : q_nope.device();

    // Make contiguous and move to device if needed
    Tensor q_nope_dev     = q_nope.contiguous().to(device);
    Tensor q_pe_dev       = q_pe.contiguous().to(device);
    Tensor ckv_cache_dev  = ckv_cache.contiguous().to(device);
    Tensor kpe_cache_dev  = kpe_cache.contiguous().to(device);
    Tensor kv_indptr_dev  = kv_indptr.contiguous().to(device);
    Tensor kv_indices_dev = kv_indices.contiguous().to(device);

    const int64_t B = q_nope_dev.size(0);
    const int64_t len_indptr = kv_indptr_dev.size(0);

    // Allocate outputs on device
    Tensor output_dev = torch::empty({B, MLA_NUM_QO_HEADS, MLA_HEAD_DIM_CKV},
                                     torch::dtype(torch::kBFloat16).device(device));
    Tensor lse_dev = torch::empty({B, MLA_NUM_QO_HEADS},
                                  torch::dtype(torch::kFloat32).device(device));

    // Launch kernel
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    const __nv_bfloat16* q_nope_ptr = reinterpret_cast<const __nv_bfloat16*>(
        q_nope_dev.data_ptr<c10::BFloat16>());
    const __nv_bfloat16* q_pe_ptr = reinterpret_cast<const __nv_bfloat16*>(
        q_pe_dev.data_ptr<c10::BFloat16>());
    const __nv_bfloat16* ckv_cache_ptr = reinterpret_cast<const __nv_bfloat16*>(
        ckv_cache_dev.data_ptr<c10::BFloat16>());
    const __nv_bfloat16* kpe_cache_ptr = reinterpret_cast<const __nv_bfloat16*>(
        kpe_cache_dev.data_ptr<c10::BFloat16>());

    const int32_t* kv_indptr_ptr = kv_indptr_dev.data_ptr<int32_t>();
    const int32_t* kv_indices_ptr = kv_indices_dev.data_ptr<int32_t>();

    __nv_bfloat16* output_ptr = reinterpret_cast<__nv_bfloat16*>(
        output_dev.data_ptr<c10::BFloat16>());
    float* lse_ptr = lse_dev.data_ptr<float>();

    float sm_scale = static_cast<float>(sm_scale_d);

    mla_paged_decode_h16_ckv512_kpe64_ps1_launcher(
        q_nope_ptr, q_pe_ptr,
        ckv_cache_ptr, kpe_cache_ptr,
        kv_indptr_ptr, kv_indices_ptr,
        static_cast<int>(B),
        static_cast<int>(len_indptr),
        sm_scale,
        output_ptr, lse_ptr,
        stream
    );

    // Check for async launch errors
    cudaError_t err_sync = cudaGetLastError();
    TORCH_CHECK(err_sync == cudaSuccess, "CUDA error after kernel launch: ", cudaGetErrorString(err_sync));

    // If original inputs were on CPU, move outputs back to CPU (synchronize stream first)
    Tensor output = output_dev;
    Tensor lse    = lse_dev;
    if (inputs_on_cpu) {
        // Ensure kernel finished before D2H copy
        cudaStreamSynchronize(stream);
        output = output_dev.cpu();
        lse    = lse_dev.cpu();
    }

    pybind11::dict result;
    result["output"] = output;
    result["lse"] = lse;
    return result;
}

// Important: Use TORCH_EXTENSION_NAME so the generated module name matches what
// torch.utils.cpp_extension.load expects at runtime.
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.doc() = "Optimized MLA paged decode kernel for h16 ckv512 kpe64 ps1 (B200)";
    m.def(
        "run",
        &run,
        pybind11::arg("q_nope"),
        pybind11::arg("q_pe"),
        pybind11::arg("ckv_cache"),
        pybind11::arg("kpe_cache"),
        pybind11::arg("kv_indptr"),
        pybind11::arg("kv_indices"),
        pybind11::arg("sm_scale"),
        "Run mla_paged_decode_h16_ckv512_kpe64_ps1 (BF16) on the current CUDA device"
    );
}
